import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

// Sea of Embers is an original, self-contained RPG slice. World data and combat are deliberately data-driven.
const $=s=>document.querySelector(s), ui={level:$('#level'),xp:$('#xp-label'),xpFill:$('#xp-fill'),hp:$('#health-fill'),hpText:$('#health-text'),en:$('#energy-fill'),enText:$('#energy-text'),beli:$('#beli'),frags:$('#fragments'),questTitle:$('#quest-title'),questDesc:$('#quest-description'),questProgress:$('#quest-progress-label'),questCount:$('#quest-count'),questXP:$('#quest-xp'),questBeli:$('#quest-beli'),interaction:$('#interaction'),interactionText:$('#interaction-text'),panel:$('#game-panel'),toast:$('#toast-stack'),sea:$('#sea-name'),island:$('#island-name')};
const seas=[
 {name:'First Sea',theme:'Windward Isles',color:0x58a783,islands:[['Windward Cay','Safe Harbor',0,0,'shore'],['Mossback Jungle','Verdant Wilds',85,-45,'jungle'],['Emberfall Atoll','Ashen Coast',-88,50,'volcanic']]},
 {name:'Second Sea',theme:'The Veiled Reach',color:0x6a8fa1,islands:[['Frostglass Port','Northern Reach',0,0,'snow'],['Gloamwood','Twilight Forest',90,-55,'dark'],['Sunkissed Ruins','Sunken Kingdom',-90,55,'desert']]},
 {name:'Third Sea',theme:'The Far Horizon',color:0xa07170,islands:[['Stormcrown','Tempest Frontier',0,0,'storm'],['Ivory Expanse','Celestial Wilds',92,-50,'sky'],['Ashen Crown','Hellfire Expanse',-92,50,'volcanic']]}
];
const fruits=[['Rocket','Common','Burst forward with a kinetic thrust.'],['Spin','Common','Aerial rotation and slicing gusts.'],['Blade','Common','Manifest sharp edges of living steel.'],['Spring','Common','Elastic leaps and impact strikes.'],['Bomb','Common','Volatile blasts and area denial.'],['Smoke','Common','Vapor veil and drifting blasts.'],['Spike','Common','Raise jagged ground formations.'],['Flame','Uncommon','Shape bright, precise fire.'],['Falcon','Uncommon','Winged dives and quick movement.'],['Ice','Uncommon','Freeze foes and skate over water.'],['Sand','Uncommon','Control abrasive wind and dunes.'],['Dark','Uncommon','Pull enemies into a gravity well.'],['Diamond','Uncommon','Harden into reflective armor.'],['Light','Rare','Dash and lance beams of light.'],['Rubber','Rare','Stretch, bounce, and absorb force.'],['Barrier','Rare','Create tactical protective walls.'],['Ghost','Rare','Summon spectral doubles.'],['Magma','Rare','Lava flows and erupting impacts.'],['Quake','Rare','Crack the ground with shockwaves.'],['Buddha','Legendary','Expand your reach in a giant form.'],['Love','Legendary','Charm and aerial heart-shaped bursts.'],['Spider','Legendary','Snare and swing on energy threads.'],['Sound','Legendary','Resonant waves with rhythmic timing.'],['Phoenix','Legendary','Soar, heal, and strike in rebirth.'],['Portal','Legendary','Blink between marked locations.'],['Rumble','Legendary','Chain lightning across the field.'],['Pain','Legendary','Repel attacks and return force.'],['Blizzard','Legendary','A roaming cyclone of ice.'],['Gravity','Mythical','Lift foes and command falling stones.'],['Mammoth','Mythical','Charge and trample in a massive form.'],['T-Rex','Mythical','Predatory pounce and primal roar.'],['Dough','Mythical','Malleable traps and heated fists.'],['Shadow','Mythical','Eclipse field and shadow minions.'],['Venom','Mythical','Toxic pools and a venomous form.'],['Control','Mythical','Shape a bounded arena of influence.'],['Spirit','Mythical','Call playful spirits of dusk and dawn.'],['Dragon','Mythical','Draconic breath, flight, and scales.'],['Leopard','Mythical','Swift feline strikes and pounce.'],['Kitsune','Mythical','Foxfire and a spectral dash.'],['Gas','Mythical','Create a drifting field of volatile gas.'],['Magnet','Mythical','Attract metal and create a magnetic storm.']];
const abilityData=[['EMBER JAB','Quick close-range fire burst',0,0],['CINDER VEIL','Concealing flame cloud · 5s',22,4],['HELLSPARK','Explosive ranged fireball · 7s',28,7],['INFERNO RING','Expanding area burst · 12s',40,12],['PHOENIX DRIFT','Flaming dash and lift · 16s',35,16]];
const state={level:1,xp:0,nextXp:120,hp:100,maxHp:100,energy:100,maxEnergy:100,beli:2500,fragments:0,stats:{Melee:1,Defense:1,Sword:1,Gun:1,'Blox Fruit':1},points:0,mastery:1,transformed:false,quest:null,questKills:0,selectedSea:0,selectedIsland:0,weather:'clear',race:'Human',inventory:['Hellfire Gas','Rusty Cutlass','Wayfarer Coat'],cooldowns:{},lastHit:0};
let scene,camera,renderer,clock,player,playerModel,water,worldGroup,enemies=[],npcs=[],effects=[],keys={},moveVector=new THREE.Vector3(),velocityY=0,onGround=true,lastTime=0,attackLock=0,dayTime=0,windTime=0,activeIsland=0,activeSea=0,stick={x:0,y:0,active:false},lastTap=0;
const islandObjects=[];
function mat(color,roughness=.9,emissive=0){return new THREE.MeshStandardMaterial({color,roughness,emissive,emissiveIntensity:emissive?1:0})}
function box(parent,x,y,z,sx,sy,sz,color,opts={}){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),mat(color,.86,opts.emissive||0));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,x,y,z,rt,rb,h,color,segments=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,segments),mat(color));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function makeTree(parent,x,z,scale=1,color=0x326b4d){cylinder(parent,x,.8*scale,z,.12*scale,.19*scale,1.6*scale,0x76513a,6);const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(.8*scale,1),mat(color));crown.position.set(x,1.8*scale,z);crown.scale.set(1,1.25,1);crown.castShadow=true;parent.add(crown);return crown}
function createIsland(data,idx,seaIndex){const [name,subtitle,x,z,biome]=data,g=new THREE.Group();g.position.set(x,0,z);g.userData={name,subtitle,biome,seaIndex,idx};scene.add(g);const colors={shore:0x78ae76,jungle:0x4d875c,volcanic:0x72594d,snow:0xb1c8cc,dark:0x415b58,desert:0xb9a16c,storm:0x62676e,sky:0x8caa91};const base=colors[biome]||0x619375;
 const shape=new THREE.Shape();shape.moveTo(-20,-14);shape.quadraticCurveTo(-26,-6,-18,5);shape.quadraticCurveTo(-22,18,-6,20);shape.quadraticCurveTo(9,24,18,14);shape.quadraticCurveTo(25,6,18,-7);shape.quadraticCurveTo(13,-20,-2,-18);shape.quadraticCurveTo(-14,-22,-20,-14);const geo=new THREE.ExtrudeGeometry(shape,{depth:2.5,bevelEnabled:true,bevelSegments:2,steps:1,bevelSize:1.2,bevelThickness:1.1,curveSegments:5});geo.rotateX(-Math.PI/2);const land=new THREE.Mesh(geo,mat(base));land.position.y=-.7;land.receiveShadow=true;land.castShadow=true;g.add(land);
 const top=new THREE.Mesh(new THREE.CircleGeometry(17,12),mat(biome==='desert'?0xc6b579:biome==='snow'?0xc8dcdb:biome==='volcanic'?0x566d54:base));top.rotation.x=-Math.PI/2;top.position.y=.48;top.scale.set(1.05,.82,1);top.receiveShadow=true;g.add(top);
 const peakColor=biome==='snow'?0xdce9e7:biome==='desert'?0x9c835c:biome==='volcanic'?0x554039:base;const hill=cylinder(g,0,2.7,0,5.5,10,5.2,peakColor,7);hill.rotation.z=.12;const hill2=cylinder(g,7,1.7,-4,3.8,6,3.5,peakColor,7);hill2.rotation.x=.15;
 const safe=cylinder(g,-8,.7,6,5.5,5.5,.15,0x68b8a0,24);safe.material.transparent=true;safe.material.opacity=.28;safe.material.emissive.set(0x1b8c71);safe.material.emissiveIntensity=.35;
 if(biome==='jungle'||biome==='dark'||biome==='shore'||biome==='sky'){for(let i=0;i<13;i++){const a=i*2.39,r=10+(i%4)*1.5;makeTree(g,Math.cos(a)*r,Math.sin(a)*r,.75+((i*7)%4)*.13,biome==='dark'?0x28463d:biome==='sky'?0x6b966c:0x377a52)}}
 if(biome==='desert'){for(let i=0;i<7;i++){const a=i*2.4,r=7+(i%3)*3;cylinder(g,Math.cos(a)*r,.9,Math.sin(a)*r,.2,.3,1.8,0x547b55,7)}}
 if(biome==='volcanic'){const lava=cylinder(g,0,5.35,0,2.3,2.5,.15,0xff6532,16);lava.material.emissive.set(0xff3511);lava.material.emissiveIntensity=2}
 // Small, original coastal settlement: huts, docks, lanterns and a central landmark.
 for(let j=0;j<3;j++){const hx=-9+j*5,hz=-7+(j%2)*2;box(g,hx,1.2,hz,3.1,2.2,2.8,j===1?0x997450:0x775743);const roof=new THREE.Mesh(new THREE.ConeGeometry(2.4,1.5,4),mat(biome==='snow'?0x667985:0x543a32));roof.position.set(hx,3,hz);roof.rotation.y=Math.PI/4;roof.castShadow=true;g.add(roof);box(g,hx,1,hz+1.42,.65,1.5,.07,0x382820)}
 box(g,1,.75,-8,7,.25,1,0x8f6849);for(let n=0;n<5;n++)box(g,1,.5,-10+n*.9,1.1,.12,1,0xad8157);
 const beacon=cylinder(g,2,1.2,5,.25,.3,2.4,0xd4ad67,7);const orb=new THREE.Mesh(new THREE.OctahedronGeometry(.35),new THREE.MeshBasicMaterial({color:0xffd793}));orb.position.set(2,2.6,5);g.add(orb);
 const questNpc=createNPC(g,-4,0,2,'Harbor Guide',0x66c9ac,'quest');const shopNpc=createNPC(g,5,0,3,'Island Trader',0xd3a65c,'shop');const enemyCount=seaIndex===0?4:5;for(let i=0;i<enemyCount;i++){const ex=5+Math.cos(i*1.6)*(7+(i%2)*2),ez=-3+Math.sin(i*1.6)*(7+(i%2)*2);const e=createEnemy(g,ex,ez,seaIndex,idx,i===enemyCount-1);enemies.push(e)}
 islandObjects.push({group:g,data,seaIndex,idx,npcs:[questNpc,shopNpc]});return g;
}
function createNPC(parent,x,z,y,name,color,type){const g=new THREE.Group();g.position.set(x,y,z);const torso=cylinder(g,0,1.1,0,.36,.4,1.05,color,8);const head=new THREE.Mesh(new THREE.SphereGeometry(.31,10,8),mat(0xe2bb91));head.position.y=1.85;head.castShadow=true;g.add(head);const hat=new THREE.Mesh(new THREE.ConeGeometry(.48,.25,8),mat(type==='quest'?0xd5b26e:0x6b5540));hat.position.y=2.15;g.add(hat);parent.add(g);const light=new THREE.PointLight(type==='quest'?0x6df1c5:0xffc96d,1.5,6);light.position.y=2.5;g.add(light);const n={group:g,name,type,baseX:x,baseZ:z,label:null};npcs.push(n);return n}
function createEnemy(parent,x,z,sea,isl,boss=false){const g=new THREE.Group();g.position.set(x,0,z);const color=boss?0x94483f:sea===0?0x817153:sea===1?0x546d72:0x745a68;const body=cylinder(g,0,.85,0,boss?.53:.4,boss?.48:.35,boss?1.55:1.25,color,8);const head=new THREE.Mesh(new THREE.SphereGeometry(boss?.4:.29,10,8),mat(0xc49376));head.position.y=boss?1.9:1.55;g.add(head);const band=box(g,0,1.6,.02,.57,.11,.44,boss?0xff7453:0x41332b);const blade=box(g,.54,.75,0,.85,.09,.13,0xcac6b7);blade.rotation.z=-.2;g.add(blade);if(boss){const horns=new THREE.Group();for(const d of [-1,1]){const h=cylinder(g,d*.28,2.35,0,.04,.16,.55,0xd8bc80,5);h.rotation.z=d*.45} }parent.add(g);const hp=boss?230:70+sea*35;const e={group:g,hp,maxHp:hp,alive:true,boss,sea,isl,baseX:x,baseZ:z,aggro:false,lastAttack:0,name:boss?['Cinder Captain','Gloam Warden','Storm Regent'][sea]:'Rogue '+['Deckhand','Scout','Raider'][isl%3],xp:boss?220:55+sea*20,beli:boss?420:70+sea*20,phase:Math.random()*6};const label=document.createElement('div');label.className='enemy-label';label.innerHTML=`<b>${e.name}</b><span><i></i></span>`;document.body.appendChild(label);e.label=label;return e}
function buildWorld(seaIndex=0,islandIndex=0){if(worldGroup){scene.remove(worldGroup)}worldGroup=new THREE.Group();scene.add(worldGroup);enemies.forEach(e=>e.label?.remove());npcs=[];enemies=[];islandObjects.length=0;const list=seas[seaIndex].islands;list.forEach((d,i)=>createIsland(d,i,seaIndex));activeSea=seaIndex;activeIsland=islandIndex;state.selectedSea=seaIndex;state.selectedIsland=islandIndex;const chosen=islandObjects[islandIndex];if(chosen){player.position.set(chosen.group.position.x+0,0,chosen.group.position.z+10);playerModel.position.copy(player.position);camera.position.set(player.position.x+19,16,player.position.z+23)}ui.sea.textContent=seas[seaIndex].name.toUpperCase();ui.island.textContent=list[islandIndex][0];$('#location-toast').innerHTML=`<span>DISCOVERED</span><b>${list[islandIndex][0]}</b><small>${seas[seaIndex].name} · ${list[islandIndex][1]}</small>`;$('#location-toast').classList.add('show');setTimeout(()=>$('#location-toast').classList.remove('show'),3500);syncPanel();}
function createPlayer(){player=new THREE.Group();const body=new THREE.Group();playerModel=body;const coat=cylinder(body,0,.92,0,.4,.35,1.12,0x314d55,8);const shirt=box(body,0,1.02,.08,.56,.67,.23,0xb47550);const head=new THREE.Mesh(new THREE.SphereGeometry(.3,12,10),mat(0xdcb590));head.position.set(0,1.82,0);head.castShadow=true;body.add(head);const hair=new THREE.Mesh(new THREE.SphereGeometry(.32,8,7),mat(0x382b28));hair.scale.set(1,.5,1.05);hair.position.set(0,2.02,-.03);body.add(hair);const hat=new THREE.Mesh(new THREE.CylinderGeometry(.49,.42,.12,12),mat(0x3c3028));hat.position.y=2.08;body.add(hat);box(body,-.28,.3,0,.2,.6,.22,0x554034);box(body,.28,.3,0,.2,.6,.22,0x554034);player.add(body);scene.add(player);player.position.set(0,0,10)}
function init(){scene=new THREE.Scene();scene.background=new THREE.Color(0x8ab9c1);scene.fog=new THREE.Fog(0x8ab9c1,65,215);camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,450);camera.position.set(18,16,30);renderer=new THREE.WebGLRenderer({canvas:$('#world'),antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
 scene.add(new THREE.HemisphereLight(0xc7e4ea,0x39464a,2.1));const sun=new THREE.DirectionalLight(0xffe0b0,3);sun.position.set(-45,65,35);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-80;sun.shadow.camera.right=80;sun.shadow.camera.top=80;sun.shadow.camera.bottom=-80;scene.add(sun);const oceanGeo=new THREE.PlaneGeometry(800,800,80,80);const positions=oceanGeo.attributes.position;for(let i=0;i<positions.count;i++){positions.setZ(i,Math.sin(positions.getX(i)*.08)*.06+Math.cos(positions.getY(i)*.11)*.05)}oceanGeo.computeVertexNormals();water=new THREE.Mesh(oceanGeo,new THREE.MeshStandardMaterial({color:0x327d91,roughness:.27,metalness:.22,transparent:true,opacity:.93}));water.rotation.x=-Math.PI/2;water.position.y=-1.05;scene.add(water);createPlayer();buildWorld(0,0);clock=new THREE.Clock();setupInputs();window.addEventListener('resize',resize);animate();setTimeout(()=>$('#loading').classList.add('done'),700);renderHUD();}
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}
function setupInputs(){window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyE')interact();if(e.code==='KeyF')togglePanel('fruit');if(e.code==='KeyI')togglePanel('inventory');if(e.code==='KeyP')togglePanel('stats');if(e.code==='KeyM')togglePanel('world');if(e.code==='KeyT')transform();if(e.code==='Digit1')attack(0);if(e.code==='Digit2')attack(1);if(e.code==='Digit3')attack(2);if(e.code==='Digit4')attack(3);if(e.code==='Digit5')attack(4);if(e.code==='Space'&&onGround){velocityY=8.5;onGround=false}if(e.code==='ShiftLeft'||e.code==='ShiftRight')dash()});window.addEventListener('keyup',e=>keys[e.code]=false);$('#world').addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;if(Date.now()-lastTap<320)return;lastTap=Date.now();attack(0)});$('#transform').onclick=transform;document.querySelectorAll('.skill').forEach((el,i)=>el.onclick=()=>attack(i));document.querySelectorAll('.rail-btn').forEach(b=>b.onclick=()=>togglePanel(b.dataset.panel));$('#map-toggle').onclick=()=>togglePanel('world');$('#menu-toggle').onclick=()=>togglePanel('world');$('#abandon-quest').onclick=()=>{state.quest=null;renderQuest()};
 $('#mobile-jump').ontouchstart=e=>{e.preventDefault();if(onGround){velocityY=8.5;onGround=false}};$('#mobile-attack').ontouchstart=e=>{e.preventDefault();attack(0)};$('#mobile-dash').ontouchstart=e=>{e.preventDefault();dash()};const stickEl=$('#mobile-stick');stickEl.addEventListener('pointerdown',e=>{stick.active=true;stickEl.setPointerCapture(e.pointerId);updateStick(e)});stickEl.addEventListener('pointermove',e=>{if(stick.active)updateStick(e)});['pointerup','pointercancel'].forEach(ev=>stickEl.addEventListener(ev,()=>{stick.active=false;stick.x=stick.y=0;stickEl.querySelector('span').style.transform=''}));document.addEventListener('click',e=>{const b=e.target.closest('[data-world-destination]');if(b){const [s,i]=b.dataset.worldDestination.split(',').map(Number);travel(s,i)}const stat=e.target.closest('[data-stat]');if(stat)allocateStat(stat.dataset.stat);const fruit=e.target.closest('[data-fruit]');if(fruit)selectFruit(fruit.dataset.fruit);const action=e.target.closest('[data-action]');if(action)performAction(action.dataset.action)});}
function updateStick(e){const r=$('#mobile-stick').getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=39;stick.x=THREE.MathUtils.clamp(dx/max,-1,1);stick.y=THREE.MathUtils.clamp(dy/max,-1,1);$('#mobile-stick span').style.transform=`translate(${stick.x*23}px,${stick.y*23}px)`}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);dayTime+=dt;windTime+=dt;updatePlayer(dt);updateEnemies(dt);updateEffects(dt);water.material.color.setHSL(.52+Math.sin(dayTime*.025)*.018,.48,.35+Math.sin(dayTime*.04)*.025);water.position.y=-1.04+Math.sin(dayTime*1.2)*.025;const sunColor=new THREE.Color().setHSL(.11+Math.sin(dayTime*.025)*.015,.56,.72);scene.children.find(o=>o.isDirectionalLight)?.color.copy(sunColor);scene.background.setHSL(.55+Math.sin(dayTime*.025)*.015,.32,.61+Math.sin(dayTime*.025)*.04);scene.fog.color.copy(scene.background);updateCamera(dt);renderer.render(scene,camera);updateLabels()}
function updatePlayer(dt){const f=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-stick.y,r=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+stick.x;moveVector.set(r,0,-f);if(moveVector.lengthSq()>1)moveVector.normalize();const speed=keys.ShiftLeft||keys.ShiftRight?10:6.5;player.position.addScaledVector(moveVector,speed*dt);player.position.x=THREE.MathUtils.clamp(player.position.x,-120,120);player.position.z=THREE.MathUtils.clamp(player.position.z,-120,120);if(moveVector.lengthSq()>.01){playerModel.rotation.y=Math.atan2(moveVector.x,-moveVector.z);playerModel.position.y=Math.sin(dayTime*11)*.035}
 velocityY-=22*dt;player.position.y+=velocityY*dt;if(player.position.y<=0){player.position.y=0;velocityY=0;onGround=true}if(state.hp<state.maxHp&&Date.now()-state.lastHit>4000)state.hp=Math.min(state.maxHp,state.hp+2*dt);state.energy=Math.min(state.maxEnergy,state.energy+7*dt);const near=getNearby();ui.interaction.style.display=near?'flex':'none';if(near)ui.interactionText.textContent=near.type==='enemy'?`Attack ${near.name}${near.boss?' · BOSS':''}`:near.name==='Harbor Guide'?(state.quest?'Ask about another contract':'Talk to the Harbor Guide'):'Trade with the Island Trader';renderHUD()}
function updateCamera(dt){const desired=new THREE.Vector3(player.position.x+17,player.position.y+13,player.position.z+22);camera.position.lerp(desired,1-Math.pow(.002,dt));camera.lookAt(player.position.x,player.position.y+1,player.position.z)}
function updateEnemies(dt){for(const e of enemies){if(!e.alive)continue;e.phase+=dt;const dist=e.group.position.distanceTo(player.position);if(dist<13)e.aggro=true;else if(dist>23)e.aggro=false;if(e.aggro&&dist>2.6){const d=player.position.clone().sub(e.group.position);d.y=0;d.normalize();e.group.position.addScaledVector(d,dt*(e.boss?1.9:1.35));e.group.rotation.y=Math.atan2(d.x,d.z)}else if(e.aggro&&dist<=2.6&&Date.now()-e.lastAttack>1400){e.lastAttack=Date.now();state.hp=Math.max(0,state.hp-(e.boss?13:7));state.lastHit=Date.now();if(state.hp<=0)respawn()}else if(!e.aggro){e.group.position.x=e.baseX+Math.sin(e.phase*.5)*.8;e.group.position.z=e.baseZ+Math.cos(e.phase*.6)*.8}e.group.position.y=Math.abs(Math.sin(e.phase*2))*.04;const p=e.group.position.clone();p.y+=2.6;p.project(camera);e.label.style.left=`${(p.x*.5+.5)*innerWidth}px`;e.label.style.top=`${(-p.y*.5+.5)*innerHeight}px`;e.label.style.display=p.z<1&&dist<32?'block':'none';e.label.querySelector('i').style.width=`${100*e.hp/e.maxHp}%`;}}
function updateLabels(){for(const n of npcs){const p=n.group.getWorldPosition(new THREE.Vector3());p.y+=2.7;p.project(camera);if(p.z<1){n.label ||= document.createElement('div');if(!n.label.isConnected){n.label.className='npc-label';n.label.innerHTML=`<span>✦</span> ${n.name}`;document.body.appendChild(n.label)}n.label.style.left=`${(p.x*.5+.5)*innerWidth}px`;n.label.style.top=`${(-p.y*.5+.5)*innerHeight}px`;n.label.style.display='block'}else if(n.label)n.label.style.display='none'}}
function getNearby(){let best=null,dist=4.2;for(const n of npcs){const d=n.group.getWorldPosition(new THREE.Vector3()).distanceTo(player.position);if(d<dist){dist=d;best=n}}for(const e of enemies){if(!e.alive)continue;const d=e.group.position.distanceTo(player.position);if(d<dist){dist=d;best={...e,type:'enemy'}}}return best}
