function init(){loadProgress();scene=new THREE.Scene();scene.background=new THREE.Color(0x8ab9c1);scene.fog=new THREE.Fog(0x8ab9c1,65,215);camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,450);camera.position.set(18,16,30);renderer=new THREE.WebGLRenderer({canvas:$('#world'),antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
 scene.add(new THREE.HemisphereLight(0xc7e4ea,0x39464a,2.1));const sun=new THREE.DirectionalLight(0xffe0b0,3);sun.position.set(-45,65,35);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-80;sun.shadow.camera.right=80;sun.shadow.camera.top=80;sun.shadow.camera.bottom=-80;scene.add(sun);const oceanGeo=new THREE.PlaneGeometry(800,800,80,80);const positions=oceanGeo.attributes.position;for(let i=0;i<positions.count;i++){positions.setZ(i,Math.sin(positions.getX(i)*.08)*.06+Math.cos(positions.getY(i)*.11)*.05)}oceanGeo.computeVertexNormals();water=new THREE.Mesh(oceanGeo,new THREE.MeshStandardMaterial({color:0x327d91,roughness:.27,metalness:.22,transparent:true,opacity:.93}));water.rotation.x=-Math.PI/2;water.position.y=-1.05;scene.add(water);createPlayer();buildWorld(state.selectedSea,state.selectedIsland);clock=new THREE.Clock();setupInputs();window.addEventListener('resize',resize);window.addEventListener('beforeunload',saveProgress);setInterval(saveProgress,5000);animate();setTimeout(()=>$('#loading').classList.add('done'),700);renderHUD();}
