function setupInputs(){window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyE')interact();if(e.code==='KeyF')togglePanel('fruit');if(e.code==='KeyI')togglePanel('inventory');if(e.code==='KeyP')togglePanel('stats');if(e.code==='KeyM')togglePanel('world');if(e.code==='KeyT')transform();if(e.code==='Digit1')attack(0);if(e.code==='Digit2')attack(1);if(e.code==='Digit3')attack(2);if(e.code==='Digit4')attack(3);if(e.code==='Digit5')attack(4);if(e.code==='Digit6')attack(5);if(e.code==='Space'&&onGround){velocityY=8.5;onGround=false}if(e.code==='ShiftLeft'||e.code==='ShiftRight')dash()});window.addEventListener('keyup',e=>keys[e.code]=false);$('#world').addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;if(Date.now()-lastTap<320)return;lastTap=Date.now();attack(0)});$('#transform').onclick=transform;document.querySelectorAll('.skill').forEach((el,i)=>el.onclick=()=>attack(i));document.querySelectorAll('.rail-btn').forEach(b=>b.onclick=()=>togglePanel(b.dataset.panel));$('#map-toggle').onclick=()=>togglePanel('world');$('#menu-toggle').onclick=()=>togglePanel('world');$('#abandon-quest').onclick=()=>{state.quest=null;renderQuest()};
 $('#mobile-jump').ontouchstart=e=>{e.preventDefault();if(onGround){velocityY=8.5;onGround=false}};$('#mobile-attack').ontouchstart=e=>{e.preventDefault();attack(0)};$('#mobile-dash').ontouchstart=e=>{e.preventDefault();dash()};const stickEl=$('#mobile-stick');stickEl.addEventListener('pointerdown',e=>{stick.active=true;stickEl.setPointerCapture(e.pointerId);updateStick(e)});stickEl.addEventListener('pointermove',e=>{if(stick.active)updateStick(e)});['pointerup','pointercancel'].forEach(ev=>stickEl.addEventListener(ev,()=>{stick.active=false;stick.x=stick.y=0;stickEl.querySelector('span').style.transform=''}));document.addEventListener('click',e=>{const b=e.target.closest('[data-world-destination]');if(b){const [s,i]=b.dataset.worldDestination.split(',').map(Number);travel(s,i)}const stat=e.target.closest('[data-stat]');if(stat)allocateStat(stat.dataset.stat);const fruit=e.target.closest('[data-fruit]');if(fruit)selectFruit(fruit.dataset.fruit);const action=e.target.closest('[data-action]');if(action)performAction(action.dataset.action)});}
function updateStick(e){const r=$('#mobile-stick').getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=39;stick.x=THREE.MathUtils.clamp(dx/max,-1,1);stick.y=THREE.MathUtils.clamp(dy/max,-1,1);$('#mobile-stick span').style.transform=`translate(${stick.x*23}px,${stick.y*23}px)`}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);dayTime+=dt;windTime+=dt;updatePlayer(dt);updateEnemies(dt);updateEffects(dt);water.material.color.setHSL(.52+Math.sin(dayTime*.025)*.018,.48,.35+Math.sin(dayTime*.04)*.025);water.position.y=-1.04+Math.sin(dayTime*1.2)*.025;const sunColor=new THREE.Color().setHSL(.11+Math.sin(dayTime*.025)*.015,.56,.72);scene.children.find(o=>o.isDirectionalLight)?.color.copy(sunColor);scene.background.setHSL(.55+Math.sin(dayTime*.025)*.015,.32,.61+Math.sin(dayTime*.025)*.04);scene.fog.color.copy(scene.background);updateCamera(dt);renderer.render(scene,camera);updateLabels()}
function updatePlayer(dt){const f=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-stick.y,r=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+stick.x;moveVector.set(r,0,-f);if(moveVector.lengthSq()>1)moveVector.normalize();const speed=keys.ShiftLeft||keys.ShiftRight?10:6.5;player.position.addScaledVector(moveVector,speed*dt);player.position.x=THREE.MathUtils.clamp(player.position.x,-120,120);player.position.z=THREE.MathUtils.clamp(player.position.z,-120,120);if(moveVector.lengthSq()>.01){playerModel.rotation.y=Math.atan2(moveVector.x,-moveVector.z);playerModel.position.y=Math.sin(dayTime*11)*.035}
 velocityY-=22*dt;player.position.y+=velocityY*dt;if(player.position.y<=0){player.position.y=0;velocityY=0;onGround=true}if(state.hp<state.maxHp&&Date.now()-state.lastHit>4000)state.hp=Math.min(state.maxHp,state.hp+2*dt);state.energy=Math.min(state.maxEnergy,state.energy+7*dt);const near=getNearby();ui.interaction.style.display=near?'flex':'none';if(near)ui.interactionText.textContent=near.type==='enemy'?`Attack ${near.name}${near.boss?' · BOSS':''}`:near.name==='Harbor Guide'?(state.quest?'Ask about another contract':'Talk to the Harbor Guide'):'Trade with the Island Trader';renderHUD()}
