 attackLock=Date.now()+260;const name=abilityData[i][0],radius=[4,5,16,10,8,15][i],damage=([18,30,58,75,48,64][i]+state.stats['Blox Fruit']*1.5+state.mastery*1.3)*(state.transformed?1.35:1);let hit=0;for(const e of enemies){if(!e.alive)continue;let d=e.group.position.distanceTo(player.position);if(i===2){const target=player.position.clone().add(new THREE.Vector3(0,0,-1).applyQuaternion(player.quaternion).multiplyScalar(8));d=e.group.position.distanceTo(target);if(d<5)makeProjectile(player.position,target,0xff7c32)}if(i===4){const dir=new THREE.Vector3(0,0,-1).applyQuaternion(player.quaternion);player.position.addScaledVector(dir,4);burst(player.position,0xffa447,1.4,24)}if(d<radius){e.hp-=damage;hit++;e.aggro=true;const away=e.group.position.clone().sub(player.position).setY(0).normalize();e.group.position.addScaledVector(away,i===3?3:1.2);floatDamage(e.group.position,Math.round(damage),i===3?'#ffc078':'#ffb37d');if(e.hp<=0)defeat(e)}}if(hit){state.hellfireMeter=Math.min(100,state.hellfireMeter+hit*7)}const col=i===3?0xff511e:i===1?0xf39243:0xffa34f;burst(player.position.clone().add(new THREE.Vector3(0,1,0)),col,[1.3,2,1.4,2.6,2,2.8][i],[8,16,15,28,18,32][i]);if(i===5){for(let n=0;n<4;n++){const pos=player.position.clone().add(new THREE.Vector3((Math.random()-.5)*8,5+Math.random()*3,(Math.random()-.5)*8));makeProjectile(pos,player.position.clone().add(new THREE.Vector3(0,0,-8).applyQuaternion(player.quaternion)),0xff6429)}}if(hit)combatText(`${name} · ${hit} hit${hit>1?'s':''}`);else if(i===0)combatText('EMBER JAB · SWING');renderHUD()}
